// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product, Fixed18, PackedFixed18, PackedUFixed18, UFixed18, IOracleProvider, JumpRateUtilizationCurve, PayoffDefinition, PayoffDefinitionLib, IProduct} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    MockController controller;
    MockOracle oracle;

    function setUp() public {
        c = new Product();
        controller = new MockController(address(this));
        oracle = new MockOracle();

        IProduct.ProductInfo memory info;
        info.name = "P";
        info.symbol = "P";
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(0),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(0),
            data: bytes30(0)
        });
        info.oracle = IOracleProvider(address(oracle));
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        vm.prank(address(controller));
        c.initialize(info);
    }

    function testFuzz_property(uint256 rawFee) public {
        UFixed18 fee = UFixed18.wrap(rawFee);

        vm.prank(address(this)); // controller's owner(uint256) returns address(this)
        bool ok;
        try c.updateFundingFee(fee) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: the funding fee can never exceed 1 (1e18 raw units).
        // Either the update reverts, or the stored fee is <= 1e18.
        assertTrue(!ok || UFixed18.unwrap(c.fundingFee()) <= 1e18);
    }
}

contract MockController {
    address public immutable productOwner;

    constructor(address owner_) {
        productOwner = owner_;
    }

    function isProduct(IProduct) external pure returns (bool) {
        return true;
    }

    function paused() external pure returns (bool) {
        return false;
    }

    function owner(uint256) external view returns (address) {
        return productOwner;
    }

    function coordinatorFor(IProduct) external pure returns (uint256) {
        return 1;
    }
}

contract MockOracle {
    function _version() internal pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }

    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return _version();
    }

    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return _version();
    }

    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return _version();
    }
}
